import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDocumentStore } from './src/document-store.js';

function scenario(onHandoff) {
  const store = createDocumentStore({ a: 'A', b: 'B', c: 'C' });
  const renders = [];
  const handoffs = [];
  const nav = createWorkspace({ store, renderDocument: value => renders.push(value), onHandoff: (leaving, navigation) => { handoffs.push(leaving); onHandoff?.(leaving, navigation); } });
  return { store, renders, handoffs, nav };
}
{
  const s = scenario();
  s.nav.open('a'); s.nav.edit('edited'); s.nav.open('b');
  assert.deepEqual(s.handoffs, [{ id: 'a', text: 'edited' }]);
  assert.deepEqual(s.renders.at(-1), { id: 'b', text: 'B' });
  assert.equal(s.store.read('a'), 'edited');
  s.nav.close();
  assert.deepEqual(s.handoffs.at(-1), { id: 'b', text: 'B' });
  s.nav.open('c'); s.nav.dispose();
  assert.equal(s.handoffs.length, 2);
}
{
  const s = scenario((leaving, nav) => { if (leaving.id === 'a') nav.open('c'); });
  s.nav.open('a'); s.nav.open('b');
  assert.deepEqual(s.renders.at(-1), { id: 'c', text: 'C' });
  s.nav.edit('changed');
  assert.equal(s.store.read('c'), 'changed');
  assert.equal(s.store.read('b'), 'B');
}
{
  const s = scenario((leaving, nav) => { if (leaving.id === 'a') nav.close(); });
  s.nav.open('a'); s.nav.open('b');
  assert.equal(s.renders.at(-1), null);
}
console.log('workspace checks passed');
EOF"

